head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > showPlaceHolderOnReadOnly]<br/>Textarea 컴포넌트가 readOnly 또는 disabled 상태일 때 placeholder 를 표시할지 설정합니다.",
    "validation" : [
        "readOnly=true 또는 disabled=true 이고 PlaceHolder 기능이 적용된 경우에 동작합니다.",
        "true 설정 시 컴포넌트가 disabled 또는 readonly 상태일때 PlaceHolder 텍스트를 표시합니다.",
        "false (default) 설정 시 readOnly 또는 disabled 상태에서 placeholder 를 표시하지 않습니다.",
        "미설정 시 기본값(false)으로 동작하여 readOnly 또는 disabled 상태에서 placeholder 를 표시하지 않습니다.",
        "Placeholder 기능은 placeholder 또는 placeholderLocaleRef 속성으로 설정합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    let showPlaceHolderOnReadOnly = con_showPlaceHolderOnReadOnly.getText();

    // target1 : disabled=true + placeholder
    let properties1 = {
        placeholder: "disabled=true",
        disabled: true,
        showPlaceHolderOnReadOnly: showPlaceHolderOnReadOnly,
    };

    // target2 : readOnly=true + placeholder
    let properties2 = {
        placeholder: "readOnly=true",
        readOnly: true,
        showPlaceHolderOnReadOnly: showPlaceHolderOnReadOnly,
    };

    let cList1 = $c.gcm.createCList(properties1);
    let cList2 = $c.gcm.createCList(properties2);

    // textarea 생성 (placeholder 확인을 위해 입력값은 비움)
    await $c.gcm.createBasicTextArea(cList1, '', 'target1');
    target1.setValue("");

    await $c.gcm.createBasicTextArea(cList2, '', 'target2');
    target2.setValue("");
}



scwin.btn_getReturn_onclick = function (e) {
    // 실제 native textarea 의 placeholder 속성 확인
    let el1 = document.getElementById("mf_target1") || document.getElementById("target1");
    let el2 = document.getElementById("mf_target2") || document.getElementById("target2");

    let ph1 = el1 ? (el1.getAttribute("placeholder") || "") : "";
    let ph2 = el2 ? (el2.getAttribute("placeholder") || "") : "";

    // render.placeholder 도 함께 출력
    let rph1 = (target1 && target1.render) ? (target1.render.placeholder || "") : "";
    let rph2 = (target2 && target2.render) ? (target2.render.placeholder || "") : "";

    wf_body_bottom.getObj("scwin").setReturnValue("target1(disabled=true) placeholder 속성 : '" + ph1 + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("target1(disabled=true) render.placeholder : '" + rph1 + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("target2(readOnly=true) placeholder 속성 : '" + ph2 + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("target2(readOnly=true) render.placeholder : '" + rph2 + "'");
};
